async function readWorkPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12000000)throw Error('请选择12MB以内的JPG、PNG或WebP照片');const bitmap=await createImageBitmap(file);try{const canvas=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);let image=canvas.toDataURL('image/jpeg',.82);if(image.length>1800000)image=canvas.toDataURL('image/jpeg',.65);if(image.length>1800000)throw Error('照片仍然较大，请选择较小图片');return image;}finally{bitmap.close();}}
let workFilter='all';
const workCategories={cut:'剪发',color:'染发',perm:'烫发'};
function worksPanel(owner){
 const list=(db.works||[]).filter(w=>(owner||w.published)&&(workFilter==='all'||w.category===workFilter));
 const reviews=db.reviewLinks||{};
 return `<div class="records-view"><div class="view-title"><div><span class="eyebrow">${owner?'商家管理':'本店作品'}</span><h1>${owner?'作品集':'本店作品'}</h1><p class="muted">${owner?'上传和管理本店作品。':'看看本店实际做过的发型。是否适合、效果与价格，请直接和店主沟通。'}</p></div>${owner?'<button data-work-action="add">添加作品</button>':''}</div><div class="actions work-filters">${Object.entries({all:'全部',...workCategories}).map(([v,l])=>`<button class="${workFilter===v?'':'secondary'}" data-work-action="filter" data-value="${v}">${l}</button>`).join('')}</div><div class="works-grid">${list.map(w=>`<article class="card work-card">${w.image?`<button class="work-cover" data-work-action="detail" data-id="${esc(w.id)}"><img src="${esc(w.image)}" alt="${esc(w.name)}" loading="lazy"></button>`:'<div class="work-no-photo">尚未上传照片</div>'}<span class="badge">${workCategories[w.category]}${owner?' · '+(w.published?'已发布':'未发布'):''}</span><h2>${esc(w.name)}</h2><p>${esc(w.description||'店主尚未填写介绍。')}</p><div class="actions"><button class="secondary" data-work-action="detail" data-id="${esc(w.id)}">查看作品</button>${owner?`<button data-work-action="edit" data-id="${esc(w.id)}">编辑</button><button class="secondary" data-work-action="toggle" data-id="${esc(w.id)}">${w.published?'下架':'发布'}</button>`:''}</div></article>`).join('')||`<section class="card empty">${owner?'还没有作品。可先添加名称、介绍和分类，照片准备好后上传并发布。':'店主尚未发布作品，敬请期待。'}</section>`}</div>${!owner?`<section class="card"><h2>顾客评价</h2><p class="muted">前往平台查看真实评价。</p><div class="actions">${reviews.meituan?`<a class="review-link" href="${esc(reviews.meituan)}" target="_blank" rel="noopener noreferrer">查看美团评价</a>`:'<span class="muted">美团评价链接待店主添加</span>'}${reviews.douyin?`<a class="review-link" href="${esc(reviews.douyin)}" target="_blank" rel="noopener noreferrer">查看抖音评价</a>`:'<span class="muted">抖音评价链接待店主添加</span>'}</div></section>`:""}</div>`;
}
function openWorkDetail(id){const w=(db.works||[]).find(w=>w.id===id);if(!w||view!=='merchant'&&!w.published)return;const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<section class="profile-modal work-detail" role="dialog" aria-modal="true" aria-label="作品详情"><div class="view-title"><h2>${esc(w.name)}</h2><button type="button" class="secondary" data-work-close>关闭</button></div>${w.image?`<img class="work-large" src="${esc(w.image)}" alt="${esc(w.name)}">`:'<p>尚未上传照片</p>'}<span class="badge">${workCategories[w.category]}</span><p>${esc(w.description)}</p><button type="button" data-work-contact>喜欢这款，联系店主</button><div class="work-contact" hidden><p>店主电话：${esc(db.settings.phone||'待店主填写')}</p><p>店主微信：${esc(db.settings.wechat||'待店主填写')}</p>${db.settings.phone&&/^[+\d -]+$/.test(db.settings.phone)?`<a href="tel:${esc(db.settings.phone)}">拨打店主电话</a>`:''}<p>参考作品：${esc(w.name)}</p><button class="secondary" type="button" data-work-copy>复制作品名称</button><p role="status"></p></div></section>`;document.body.appendChild(modal);modal.querySelector('[data-work-close]').onclick=()=>modal.remove();modal.querySelector('[data-work-contact]').onclick=()=>modal.querySelector('.work-contact').hidden=false;modal.querySelector('[data-work-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(w.name);modal.querySelector('[role="status"]').textContent='作品名称已复制，可粘贴给店主。';}catch{modal.querySelector('[role="status"]').textContent='请手动复制上面的作品名称。';}};}
async function persistWork(w){if(view!=='merchant'||globalThis.SalonNetwork?.clientMode)throw Error('客户只能查看作品');if(globalThis.SalonNetwork?.ready)return SalonNetwork.saveWork(w);db.works=db.works||[];const i=db.works.findIndex(x=>x.id===w.id);if(i<0)db.works.push(w);else db.works[i]=w;save();render();}
function openWorkEditor(id){if(view!=='merchant'||globalThis.SalonNetwork?.clientMode)return;const w=(db.works||[]).find(w=>w.id===id)||{id:uid(),category:'cut'},modal=document.createElement('div');let image=w.image||'';modal.className='modal-backdrop';modal.innerHTML=`<section class="profile-modal work-editor" role="dialog" aria-modal="true" aria-label="编辑作品"><div class="view-title"><h2>${id?'编辑作品':'添加作品'}</h2><button class="secondary" type="button" data-work-close>关闭</button></div><form><label>作品名称<input name="name" maxlength="60" value="${esc(w.name||'')}" required></label><label>分类<select name="category">${Object.entries(workCategories).map(([v,l])=>opt(v,l,w.category)).join('')}</select></label><label>简单介绍<textarea name="description" maxlength="1000">${esc(w.description||'')}</textarea></label><label>上传照片（可稍后添加）<input name="image" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="work-upload-preview">${image?`<img src="${esc(image)}" alt="作品预览">`:'尚未上传照片'}</div><label class="check"><input type="checkbox" name="consent" ${w.consent?'checked':''}>已取得照片展示授权，优先使用背面或局部照片</label><label class="check"><input type="checkbox" name="published" ${w.published?'checked':''}>发布到客户端（未勾选则保存草稿）</label><p role="status"></p><button type="submit">保存作品</button></form></section>`;document.body.appendChild(modal);modal.querySelector('[data-work-close]').onclick=()=>modal.remove();let imageLoading=false;modal.querySelector('[name="image"]').onchange=async e=>{const file=e.target.files[0];if(!file)return;imageLoading=true;try{image=await readWorkPhoto(file);modal.querySelector('.work-upload-preview').innerHTML=`<img src="${esc(image)}" alt="作品预览">`;}catch(err){modal.querySelector('[role="status"]').textContent=err.message;}finally{imageLoading=false;}};modal.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type="submit"]'),d=new FormData(e.target);button.disabled=true;try{if(imageLoading)throw Error('照片正在处理，请稍等');const published=d.has('published'),consent=d.has('consent');if(published&&(!image||!consent))throw Error('发布前请上传照片并确认展示授权');await persistWork({...w,name:d.get('name').trim(),category:d.get('category'),description:d.get('description').trim(),image,published,consent});modal.remove();render();toast('作品已保存');}catch(err){modal.querySelector('[role="status"]').textContent=err.message;}finally{button.disabled=false;}};}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-work-action]');if(!b)return;e.preventDefault();const a=b.dataset.workAction;try{if(a==='filter'){workFilter=b.dataset.value;render();}else if(a==='add'||a==='edit')openWorkEditor(b.dataset.id);else if(a==='detail')openWorkDetail(b.dataset.id);else if(a==='toggle'){const w=db.works.find(x=>x.id===b.dataset.id);await persistWork({...w,published:!w.published});toast(w.published?'作品已下架':'作品已发布');}}catch(err){toast(err.message);}});
document.addEventListener('submit',async e=>{if(e.target.id!=='work-contact-form')return;e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),status=f.querySelector('.work-form-status');try{if(view!=='merchant'||globalThis.SalonNetwork?.clientMode)throw Error('无修改权限');if(globalThis.SalonNetwork?.ready)await SalonNetwork.saveWorkContact(d);else{db.settings.phone=d.phone;db.settings.wechat=d.wechat;db.reviewLinks={meituan:d.meituan,douyin:d.douyin};save();}toast('联系方式与评价入口已保存');}catch(err){status.textContent=err.message;}});